"""Text-to-SQL harness: draft -> execute -> grounded repair.

Contract (fixed): solve(task, env) -> {"sql": str}
  task  {"id", "db_id", "question", "hint"}
  env.chat(messages, max_tokens=None) -> str     capped per task: env.max_calls
  env.schema(db_id) -> str
  env.execute(sql, max_rows=20) -> dict          {ok, columns, rows, n_rows, error}
  env.descriptions(db_id) -> str
  env.prompt(name) -> str
  env.config -> dict
"""

import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)
IDENT = re.compile(r"[A-Za-z_][A-Za-z_0-9]*")
CREATE_RE = re.compile(
    r"CREATE\s+(?:TEMP\s+|TEMPORARY\s+)?(?:TABLE|VIEW)\s+(?:IF\s+NOT\s+EXISTS\s+)?"
    r"[\"'`\[]?([A-Za-z_][A-Za-z_0-9]*)[\"'`\]]?\s*\((.*)",
    re.S | re.I,
)
QUOTED = re.compile(r"'([^']{2,60})'|\"([^\"]{2,60})\"")

STOP = set(
    """a an the of for in on at to and or with without by from as is are was were be been being
    that this these those which what who whom whose where when how why list show find give tell
    me all any each every both either neither none no not nor do does did done have has had
    having i you he she it they them their there here his her its our your my mine also than
    then so such more most less least many much few some same other others only just very
    number numbers count total sum average mean maximum minimum max min top highest lowest
    greatest smallest best worst first second third last name names id ids detail details
    information info value values result results record records row rows table tables column
    columns database data please question answer following between among during after before
    above below over under out up down off again further once ever never always usually
    people person man men woman women thing things one two three four five six seven eight
    nine ten year years month months day days time times date dates amount amounts per
    """.split()
)


def extract_sql(text):
    text = text or ""
    blocks = [b.strip() for b in SQL_BLOCK.findall(text) if b.strip()]
    cand = blocks[-1] if blocks else text
    if not blocks:
        # take the last SELECT/WITH statement if the model added prose
        m = list(re.finditer(r"(?is)\b(with|select)\b", cand))
        if m:
            cand = cand[m[-1].start():]
    cand = cand.strip()
    cand = re.sub(r"^sql\s*:\s*", "", cand, flags=re.I).strip()
    cand = cand.rstrip(";").strip()
    return cand


def _safe(fn, *a, **k):
    try:
        return fn(*a, **k)
    except Exception:
        return None


def schema_tables(schema):
    """[(table, [column, ...])] parsed from CREATE statements."""
    out = []
    for m in CREATE_RE.finditer(schema or ""):
        table = m.group(1)
        body = m.group(2)
        cols = []
        depth = 0
        cur = ""
        parts = []
        for ch in body:
            if ch == "(":
                depth += 1
            elif ch == ")":
                if depth == 0:
                    break
                depth -= 1
            if ch == "," and depth == 0:
                parts.append(cur)
                cur = ""
            else:
                cur += ch
        parts.append(cur)
        for p in parts:
            p = p.strip()
            if not p:
                continue
            head = p.split()[0].strip('"`[]\'')
            if head.upper() in (
                "PRIMARY", "FOREIGN", "UNIQUE", "CHECK", "CONSTRAINT", "KEY", "INDEX"
            ):
                continue
            if IDENT.fullmatch(head):
                cols.append(head)
        if cols:
            out.append((table, cols))
    return out


def literals_from(task):
    """Candidate string values mentioned in the question / hint."""
    text = (task.get("question") or "") + " " + (task.get("hint") or "")
    cands = []
    for m in QUOTED.finditer(text):
        v = (m.group(1) or m.group(2) or "").strip()
        if v:
            cands.append(v)
    # unquoted capitalized phrases / long tokens (proper nouns, titles)
    for m in re.finditer(r"[A-Za-z][A-Za-z0-9_'\-]*(?:\s+[A-Za-z][A-Za-z0-9_'\-]*)*", text):
        phrase = m.group(0).strip()
        words = phrase.split()
        keep = [w for w in words if w.lower() not in STOP and len(w) > 2]
        if not keep:
            continue
        if len(keep) == 1 and not (words[0][:1].isupper() or len(keep[0]) > 5):
            continue
        cands.append(" ".join(keep))
        if len(keep) > 1:
            cands.extend(keep)
    seen = set()
    uniq = []
    for c in cands:
        k = c.lower()
        if k in seen or k in STOP or len(c) < 3:
            continue
        seen.add(k)
        uniq.append(c)
    return uniq


def probe_values(env, schema, lits, limit_lit, limit_val):
    """Look up how the mentioned literals are really stored (case/spacing/wording)."""
    tables = schema_tables(schema)
    notes = []
    used = 0
    for lit in lits[:limit_lit]:
        core = lit.strip().strip("%").strip()
        if len(core) < 3:
            continue
        stem = core.split()[0] if " " in core else core
        hits = []
        for table, cols in tables:
            for col in cols:
                q = (
                    'SELECT DISTINCT "%s" FROM "%s" WHERE "%s" LIKE \'%%%s%%\' LIMIT %d'
                    % (col, table, col, stem.replace("'", "''"), limit_val)
                )
                r = _safe(env.execute, q, max_rows=limit_val)
                used += 1
                if not r or not r.get("ok"):
                    continue
                for row in r.get("rows") or []:
                    if row and isinstance(row[0], str):
                        hits.append("%s.%s = %r" % (table, col, row[0]))
                if len(hits) >= limit_val:
                    break
            if len(hits) >= limit_val:
                break
        if hits:
            notes.append("Stored values matching %r:\n  " % lit + "\n  ".join(hits[:limit_val]))
        else:
            notes.append(
                "No stored text anywhere matches %r (try a shorter stem, another column, "
                "or a numeric/code representation)." % lit
            )
        if used > 120:
            break
    return "\n".join(notes)


def describe_result(r):
    if r is None:
        return "The query could not be executed."
    if not r.get("ok"):
        return "SQL ERROR: %s" % (r.get("error") or "unknown error")
    rows = r.get("rows") or []
    if not rows:
        return "The query ran but returned 0 rows."
    head = rows[:5]
    return "The query returned %s row(s), columns %s, first rows: %s" % (
        r.get("n_rows", len(rows)), r.get("columns"), head
    )


def solve(task, env):
    cfg = env.config or {}
    schema = _safe(env.schema, task["db_id"]) or ""
    desc = _safe(env.descriptions, task["db_id"]) or ""
    user = "Database: %s\n\nSchema:\n%s\n" % (task["db_id"], schema)
    if desc.strip():
        user += "\nColumn descriptions:\n%s\n" % desc.strip()[:2500]
    user += "\nQuestion: %s" % task["question"]
    if task.get("hint"):
        user += "\nHint: %s" % task["hint"]
    messages = [
        {"role": "system", "content": env.prompt("system_prompt.md")},
        {"role": "user", "content": user},
    ]
    reply = env.chat(messages, max_tokens=cfg.get("max_tokens", 1400))
    sql = extract_sql(reply)
    if not sql:
        return {"sql": "SELECT 1"}

    res = _safe(env.execute, sql, max_rows=20)
    ok = bool(res and res.get("ok"))
    empty = ok and not (res.get("rows") or [])
    calls_left = getattr(env, "max_calls", 2) - 1
    if calls_left <= 0 or (ok and not empty):
        return {"sql": sql}

    feedback = "Your draft query was:\n```sql\n%s\n```\n%s\n" % (sql, describe_result(res))
    if empty or not ok:
        lits = literals_from(task)
        notes = probe_values(
            env,
            schema,
            lits,
            int(cfg.get("probe_literals", 6)),
            int(cfg.get("probe_values_per_literal", 6)),
        )
        if notes:
            feedback += "\nGrounding probe against the real data:\n%s\n" % notes
    feedback += (
        "\nReconsider the draft: are the join keys, the filtered column, and the literal "
        "spelling/case/spacing right? Is the projected column list the one the question asks "
        "for (whole entity -> all columns; named attributes -> only those)? If the result is "
        "empty because of an exact-match or one-directional-relation assumption, relax it "
        "(trim + LIKE, check both columns). Keep the query correct for the question, not just "
        "non-empty. Output the corrected query in a single ```sql block."
    )
    messages = messages + [
        {"role": "assistant", "content": reply},
        {"role": "user", "content": feedback},
    ]
    reply2 = _safe(
        env.chat, messages, max_tokens=cfg.get("repair_max_tokens", cfg.get("max_tokens", 1400))
    )
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}
    res2 = _safe(env.execute, sql2, max_rows=20)
    if res2 and res2.get("ok"):
        return {"sql": sql2}
    if ok:
        return {"sql": sql}
    return {"sql": sql2}

